SELECT *
FROM com_delivery_scope_project_version
WHERE tenant_id = #{tenantId}
  AND project_id = #{projectId}
  AND deleted = b'0'
FOR UPDATE

SELECT order_line_id AS orderLineId, MAX(allocation_version) AS maxAllocationVersion
FROM com_delivery_scope
WHERE tenant_id = #{tenantId}
  AND project_id = #{projectId}
  AND deleted = b'0'
  AND order_line_id IN
  #{id}
GROUP BY order_line_id
ORDER BY order_line_id

mapper.update:
UPDATE com_delivery_scope
SET effective_to = #{effectiveTo}, updater = #{actor}, update_time = #{now}, version = version + 1
WHERE tenant_id = #{tenantId}
  AND id = #{scopeId}
  AND version = #{expectedVersion}
  AND scope_status IN ('ACTIVE', 'CONFLICT')
  AND effective_to IS NULL
  AND deleted = b'0'

UPDATE com_delivery_scope_detail
SET detail_status = 'RELEASED', updater = #{actor}, update_time = #{now}, version = version + 1
WHERE tenant_id = #{tenantId}
  AND delivery_scope_id = #{scopeId}
  AND detail_status = 'ACTIVE'
  AND deleted = b'0'

UPDATE com_delivery_scope_project_version
SET scope_version = #{newScopeVersion}, payload_version = #{newPayloadVersion},
    last_change_type = #{changeType}, updater = #{actor}, update_time = #{now}, version = version + 1
WHERE tenant_id = #{tenantId}
  AND project_id = #{projectId}
  AND scope_version = #{expectedScopeVersion}
  AND version = #{expectedRowVersion}
  AND deleted = b'0'
